Item.method_code:
const additionalData = target.additional_data || {};
const { itemTypeName, getState } = options;
const state = getState();
if (state.grid.selectedRows.length === 0) {
	const disabled = additionalData.actionType !== 'item' && aras.canInvokeActionImpl(additionalData.canExecuteMethodName, additionalData.location);
	return { disabled: !disabled, hidden: additionalData.actionType === 'item' };
}


const areAllItemsNew = state.grid.selectedRows.every(rowId =>
	ArasModules.item.isNew(itemTypeName, rowId)
);
if (areAllItemsNew) {
	return { disabled: true, hidden: false };
}

const currentItemType = options.itemType;
const isPolymorphic = currentItemType.implementation_type === 'polymorphic';

const rowId = state.grid.selectedRows[0];
const hidden =
	isPolymorphic &&
	(state.grid.selectedRows.length > 1 ||
	options.rows.get(rowId, 'itemtype') !== additionalData.itemTypeId);

const canExecute = aras.canInvokeActionImpl(additionalData.canExecuteMethodName, additionalData.location);
return { disabled: !canExecute, hidden };
